const screen3 = document.querySelector('.screen3')
const tabsScreen3Btn = screen3.querySelectorAll('.screen3__title');
const tabsScreen3Content = screen3.querySelectorAll('.screen3__inner');

if (screen3) {
  tabsScreen3Btn.forEach((btn, index) => {
    btn.addEventListener('click', () => {
      if (window.innerWidth >= 1025) return;
      const isActive = tabsScreen3Content[index].classList.contains('screen3__inner_shown');

      tabsScreen3Content.forEach((content, i) => {
        if (i !== index) {
          content.classList.remove('screen3__inner_shown');
        }
      })

      if (!isActive) {
        tabsScreen3Content[index].classList.add('screen3__inner_shown');
      } else {
        tabsScreen3Content[index].classList.remove('screen3__inner_shown');
      }
    })
  })

  window.addEventListener('resize', () => {
    tabsScreen3Content.forEach((content) => {
      content.classList.remove('screen3__inner_shown');
    })
  })
}





